    }
}

@Composable
private fun TVProductDetails(
    modifier: Modifier = Modifier, details: Details, onPlayClick: () -> Unit
) {
    Box(
        modifier = modifier.fillMaxSize()
    ) {
        val background = MaterialTheme.colorScheme.surface
        val state = rememberPagerState(pageCount = { 2 })
        AsyncImage(
            model = details.background,
            contentDescription = "Product Banner",
            modifier = Modifier
                .fillMaxSize()
                .drawWithContent {
                    drawContent()
                    drawRect(
                        brush = Brush.horizontalGradient(
                            colors = listOf(
                                background.copy(alpha = 0.8f), background.copy(alpha = 0.1f)
                            ), startX = 0.0f, endX = size.width
                        )
                    )
                }
                .align(Alignment.TopCenter),
            contentScale = ContentScale.Crop)

        VerticalPager(
            state = state,
        ) { page ->
            when (page) {
                0 -> {
                    key("content_detail") {
                        Box(
                            modifier = Modifier
                                .fillMaxSize(),
                            contentAlignment = Alignment.BottomCenter
                        ) {
                            ContentDetail(
                                Modifier
                                    .fillMaxSize()
                                    .padding(start = 72.dp, top = 120.dp),
                                details = details,
                                onPlayClick = onPlayClick
                            )

                            ArrowDownButton(
                                modifier = Modifier.align(Alignment.Center),
                                text = "More Details",
                                icon = Icons.Default.KeyboardDoubleArrowDown,
                                onClick = { }
                            )
                        }
                    }
                }

                else -> {
                    key("more_details") {
                        Box(
                            modifier = Modifier
                                .fillMaxSize(),
                            contentAlignment = Alignment.TopCenter
                        ) {
                            MoreDetailsSection(
                                modifier = Modifier
                                    .fillMaxSize()
                                    .padding(top = 90.dp),
                                details = details
                            )

                            ArrowDownButton(
                                modifier = Modifier.align(Alignment.BottomCenter),
                                text = "Press Up",
                                icon = Icons.Default.KeyboardDoubleArrowUp,
                                onClick = { }
                            )
                        }
                    }
                }
            }
        }
    }
}

