                                text = "92%", style = MaterialTheme.typography.headlineMedium.copy(
                                    fontWeight = FontWeight.Bold
                                ), color = MaterialTheme.colorScheme.onBackground
                            )
                        }
                    }
                }
            }
            item {
                RatingCard(
                    modifier = Modifier
                        .width(cardWidthPx)
                        .height(cardWidthPx),
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxHeight()
                            .padding(16.dp),
                        verticalArrangement = Arrangement.spacedBy(
                            16.dp, Alignment.CenterVertically
                        ),
                    ) {
                        Text(
                            text = "IMDb", style = MaterialTheme.typography.bodyMedium.copy(
                                fontWeight = FontWeight.Bold
                            ), color = MaterialTheme.colorScheme.onSurface
                        )
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Icon(
                                Icons.Default.Star,
                                contentDescription = "Rating",
                                modifier = Modifier.size(32.dp)
                            )
                            Spacer(Modifier.size(8.dp))
                            Text(
                                text = "8.3/10",
                                style = MaterialTheme.typography.headlineMedium.copy(
                                    fontWeight = FontWeight.Bold
                                ),
                                color = MaterialTheme.colorScheme.onBackground
                            )
                        }
                    }
                }
            }
            item {
                RatingCard(
                    modifier = Modifier
                        .width(cardWidthPx)
                        .height(cardWidthPx),
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxHeight()
                            .padding(16.dp),
                        verticalArrangement = Arrangement.spacedBy(
                            16.dp, Alignment.CenterVertically
                        ),
                    ) {
                        Text(
                            text = "Metacritic", style = MaterialTheme.typography.bodyMedium.copy(
                                fontWeight = FontWeight.Bold
                            ), color = MaterialTheme.colorScheme.onSurface
                        )
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Icon(
                                Icons.Default.Feedback,
                                contentDescription = "Rating",
                                modifier = Modifier.size(32.dp)
                            )
                            Spacer(Modifier.size(8.dp))
                            Text(
                                text = "Generally Favorable",
                                style = MaterialTheme.typography.bodyLarge.copy(
                                    fontWeight = FontWeight.Bold
                                ),
                                color = MaterialTheme.colorScheme.onBackground
                            )
                        }
                    }
                }
            }
        }
    }
}

