                    contentDescription = "My location",
                    tint = PrimaryBlue,
                )
            }
        }
        IconButton(onClick = onClose) {
            Icon(Icons.Filled.Close, contentDescription = "Hide search", tint = OnSurfaceMuted)
        }
    }
}

